def get_components(adj, n):
    visited = set()
    components = []
    for start in range(n):
        if start not in visited:
            comp = set()
            queue = [start]
            visited.add(start)
            while queue:
                node = queue.pop(0)
                comp.add(node)
                for neighbor in adj[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            components.append(comp)
    return components

