# Combine all edges
all_edges = []
for u, v in fixed_edges:
    if u > v:
        u, v = v, u
    all_edges.append((u, v))

for u, v in added_edges:
    if u > v:
        u, v = v, u
    all_edges.append((u, v))

# Remove duplicates and sort
